
package dev.myst.client;
import dev.myst.client.module.*;import dev.myst.client.module.Module;import dev.myst.client.module.Module.*;import dev.myst.client.render.Render2D;import net.minecraft.client.gui.*;import net.minecraft.client.input.KeyInput;import net.minecraft.client.gui.screen.Screen;import net.minecraft.text.Text;import org.lwjgl.glfw.GLFW;import java.util.*;
public final class ClickGuiScreen extends Screen{
 private Category tab=Category.VISUALS;private int scroll;private double smooth;private Module binding;private int x,y,w,h;private static final int BG=0xEB111217,CARD=0xFF1B1D26,WHITE=0xFFF4F2F9,MUTED=0xFF9997A8,ACCENT=0xFFAA79FF;
 public ClickGuiScreen(){super(Text.literal("Myst Visuals"));}
 @Override protected void init(){w=Math.min(620,width-16);h=Math.min(390,height-16);x=(width-w)/2;y=(height-h)/2;}
 @Override public void render(DrawContext c,int mx,int my,float dt){c.fill(0,0,width,height,0x77000000);Render2D.drawShadow(c,x,y,w,h,15,0xAA000000,7,6);Render2D.drawRoundedRect(c,x,y,w,h,15,BG);Render2D.drawRoundedOutline(c,x,y,w,h,15,1,0xFF383744);Render2D.drawRoundedRect(c,x+14,y+14,36,36,10,ACCENT);c.drawText(textRenderer,"M",x+27,y+27,WHITE,false);c.drawText(textRenderer,"MYST VISUALS",x+60,y+16,WHITE,false);c.drawText(textRenderer,"CLIENT CONTROL CENTER",x+60,y+29,MUTED,false);
  Category[] tabs={Category.VISUALS,Category.WORLD,Category.HUD,Category.MARKS,Category.SETTINGS};for(int i=0;i<tabs.length;i++){int yy=y+66+i*38;boolean a=tab==tabs[i];if(a)Render2D.drawRoundedRect(c,x+14,yy,116,31,8,0xFF292235);if(a)Render2D.drawRoundedRect(c,x+14,yy+5,3,21,2,ACCENT);c.drawText(textRenderer,tabs[i].label(),x+27,yy+11,a?WHITE:MUTED,false);}
  int left=x+146,top=y+66,bottom=y+h-18;c.drawText(textRenderer,tab.label().toUpperCase(Locale.ROOT),left,y+25,WHITE,false);c.enableScissor(left,top,x+w-16,bottom);int yy=top+4-(int)smooth;
  for(Module m:ModuleManager.all())if(m.category()==tab){int ch=m.settings().isEmpty()?66:94;Render2D.drawRoundedRect(c,left,yy,w-162,ch,10,CARD);c.drawText(textRenderer,m.name(),left+13,yy+10,WHITE,false);c.drawText(textRenderer,m.description(),left+13,yy+26,MUTED,false);Render2D.drawRoundedRect(c,x+w-70,yy+12,40,20,10,m.enabled()?ACCENT:0xFF44434E);Render2D.drawRoundedRect(c,x+w-(m.enabled()?48:68),yy+14,16,16,8,0xFFF7F5FC);
   if(binding==m)c.drawText(textRenderer,"PRESS KEY • ESC/DEL = NONE",left+13,yy+49,ACCENT,false);else c.drawText(textRenderer,"BIND: "+(m.keyCode()==0?"[NONE]":"["+GLFW.glfwGetKeyName(m.keyCode(),0)+"]"),left+13,yy+49,MUTED,false);
   int sx=left+225;for(Setting<?> st:m.settings()){String label=st.name();if(st instanceof BooleanSetting b)label+=": "+(b.get()?"ON":"OFF");else if(st instanceof SliderSetting sl)label+=": "+String.format(Locale.ROOT,"%.1f",sl.get());else if(st instanceof ColorSetting co)label+=": #"+Integer.toHexString(co.get());else if(st instanceof ModeSetting mo)label+=": "+mo.get();c.drawText(textRenderer,label,sx,yy+70,WHITE,false);sx+=105;}yy+=ch+10;}
  c.disableScissor();smooth+=(scroll-smooth)*.25;Render2D.drawRoundedRect(c,x+w-144,y+h-43,126,27,8,0xFF292235);c.drawText(textRenderer,"HUD EDITOR",x+w-129,y+h-33,WHITE,false);c.drawText(textRenderer,"K / RIGHT SHIFT • ESC",x+18,y+h-31,MUTED,false);super.render(c,mx,my,dt);}
 @Override public boolean mouseClicked(Click click,boolean dbl){int mx=(int)click.x(),my=(int)click.y();if(click.button()==0){if(mx>=x+w-150&&my>=y+h-48){client.setScreen(new HudEditorScreen());return true;}Category[] tabs={Category.VISUALS,Category.WORLD,Category.HUD,Category.MARKS,Category.SETTINGS};for(int i=0;i<tabs.length;i++)if(mx>=x+10&&mx<=x+138&&my>=y+64+i*38&&my<=y+95+i*38){tab=tabs[i];scroll=0;smooth=0;return true;}
  int left=x+146,yy=y+70-(int)smooth;for(Module m:ModuleManager.all())if(m.category()==tab){int ch=m.settings().isEmpty()?66:94;if(mx>=left&&mx<=x+w-16&&my>=yy&&my<=yy+ch){if(binding==m){binding=null;return true;}if(mx>x+w-78&&my<yy+43){m.toggle();ConfigManager.save();return true;}if(my<yy+43){m.toggle();ConfigManager.save();return true;}if(my<yy+65&&mx<left+205){binding=m;return true;}if(mx>=left+215)for(Setting<?> st:m.settings()){if(st instanceof BooleanSetting b)b.toggle();else if(st instanceof SliderSetting sl)sl.set(sl.get()+sl.step());else if(st instanceof ColorSetting co)co.set(co.get()==0xFFAA79FF?0xFF55DDF2:0xFFAA79FF);else if(st instanceof ModeSetting mo)mo.next();ConfigManager.save();return true;}}yy+=ch+10;}}return super.mouseClicked(click,dbl);}
 @Override public boolean keyPressed(KeyInput input){int key=input.key();if(binding!=null){binding.keyCode(key==GLFW.GLFW_KEY_ESCAPE||key==GLFW.GLFW_KEY_DELETE?0:key);binding=null;ConfigManager.save();return true;}if(key==GLFW.GLFW_KEY_ESCAPE){close();return true;}return super.keyPressed(input);}
 @Override public boolean mouseScrolled(double mx,double my,double hx,double vy){scroll=Math.max(0,Math.min(10000,scroll-(int)(vy*28)));return true;}@Override public boolean shouldPause(){return false;}
}
